  // 批量创建记录
  async batchCreateRecords(
    appToken: string,
    tableId: string,
    records: Array<{ fields: Record<string, any> }>
  ) {
    const resp = await this.client.bitable.appTableRecord.batchCreate({
      path: { app_token: appToken, table_id: tableId },
      data: { records },
    });

    if (resp.code !== 0) {
      throw new Error(`批量创建记录失败: ${resp.msg}`);
    }
    return resp.data;
  }

  // 更新单条记录
  async updateRecord(
    appToken: string,
    tableId: string,
    recordId: string,
